-- ── story 9-3c: ledger anchoring and chain alerts ──────────────────────────
-- Generated by drizzle-kit (the three tables, the anchor `kind` column, the
-- indexes) and hand-amended below the marker: the CHECKs, the append-only
-- triggers of the WORM copy table, the widened notifications source CHECK,
-- RLS and the post-migration probe (drizzle-kit is blind to all five;
-- `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive only: three new tables (written only by the inventory module —
-- pinned by test/architecture.spec.ts) and one NOT NULL column on
-- `ledger_anchors` with a CONSTANT default — the PG11+ fast default: no table
-- rewrite, and ADD COLUMN fires no row trigger (the append-only guard is a
-- BEFORE UPDATE/DELETE row trigger). Every existing anchor reads `verified`,
-- which is what it was. No data statement — no pre-flight, no fail-fast. No
-- foreign keys (IMPLEMENTATION-GUIDE §3).
CREATE TABLE "ledger_anchor_worm_copies" (
	"anchor_id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"bucket" text NOT NULL,
	"object_key" text NOT NULL,
	"version_id" text NOT NULL,
	"retain_until" timestamp with time zone NOT NULL,
	"copied_at" timestamp with time zone NOT NULL
);
--> statement-breakpoint
CREATE TABLE "ledger_chain_breaks" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"first_seq" integer NOT NULL,
	"anchor_id" uuid,
	"reason" text NOT NULL,
	"detected_by" text NOT NULL,
	"detected_at" timestamp with time zone NOT NULL,
	"acknowledged_by" uuid,
	"acknowledged_at" timestamp with time zone
);
--> statement-breakpoint
CREATE TABLE "ledger_integrity_state" (
	"tenant_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"legacy_through_seq" integer NOT NULL,
	"baselined_at" timestamp with time zone NOT NULL,
	"verified_through_seq" integer,
	"verified_at" timestamp with time zone,
	"broken_at_seq" integer,
	"broken_detected_at" timestamp with time zone,
	"reverify_after_seq" integer DEFAULT 0 NOT NULL,
	"last_run_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_integrity_state_tenant_id_warehouse_id_pk" PRIMARY KEY("tenant_id","warehouse_id")
);
--> statement-breakpoint
ALTER TABLE "ledger_anchors" ADD COLUMN "kind" text DEFAULT 'verified' NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "ledger_chain_breaks_tenant_warehouse_kind_seq_unique" ON "ledger_chain_breaks" USING btree ("tenant_id","warehouse_id","kind","first_seq");--> statement-breakpoint
CREATE INDEX "ledger_chain_breaks_tenant_warehouse_detected_idx" ON "ledger_chain_breaks" USING btree ("tenant_id","warehouse_id","detected_at" DESC NULLS LAST);--> statement-breakpoint
-- ── hand-amended: the controlled vocabularies (IMPLEMENTATION-GUIDE §4) ────
-- Pinned against `LEDGER_ANCHOR_KINDS`, `LEDGER_CHAIN_BREAK_KINDS` and
-- `LEDGER_CHAIN_BREAK_DETECTORS` (schema.ts) by test/ledger-integrity.spec.ts.
-- Every column here is NOT NULL, so no arm needs an IS NULL guard.
ALTER TABLE "ledger_anchors" ADD CONSTRAINT "ledger_anchors_kind_check" CHECK ("kind" IN ('verified', 'legacy'));--> statement-breakpoint
ALTER TABLE "ledger_chain_breaks" ADD CONSTRAINT "ledger_chain_breaks_kind_check" CHECK ("kind" IN ('chain', 'worm'));--> statement-breakpoint
ALTER TABLE "ledger_chain_breaks" ADD CONSTRAINT "ledger_chain_breaks_detected_by_check" CHECK ("detected_by" IN ('anchor', 'reverify', 'verify'));--> statement-breakpoint
-- ── hand-amended: the break row's shape ───────────────────────────────────
--   * the two acknowledgement columns are both null or both set;
--   * a `worm` break names its anchor and only a `worm` break does
--     (`kind` is NOT NULL, so both sides of each equality are never NULL);
--   * a seq is 1-based.
ALTER TABLE "ledger_chain_breaks" ADD CONSTRAINT "ledger_chain_breaks_ack_check" CHECK (
	("acknowledged_by" IS NULL) = ("acknowledged_at" IS NULL)
);--> statement-breakpoint
ALTER TABLE "ledger_chain_breaks" ADD CONSTRAINT "ledger_chain_breaks_anchor_check" CHECK (
	("kind" = 'worm') = ("anchor_id" IS NOT NULL)
);--> statement-breakpoint
ALTER TABLE "ledger_chain_breaks" ADD CONSTRAINT "ledger_chain_breaks_first_seq_check" CHECK ("first_seq" >= 1);--> statement-breakpoint
-- ── hand-amended: the integrity state's shape ─────────────────────────────
-- Seqs are never negative (0 = "none": an empty or un-anchored warehouse);
-- a break seq is 1-based and travels with the instant it was first detected.
ALTER TABLE "ledger_integrity_state" ADD CONSTRAINT "ledger_integrity_state_seq_check" CHECK (
	"legacy_through_seq" >= 0
	AND "reverify_after_seq" >= 0
	AND ("verified_through_seq" IS NULL OR "verified_through_seq" >= 0)
);--> statement-breakpoint
ALTER TABLE "ledger_integrity_state" ADD CONSTRAINT "ledger_integrity_state_broken_check" CHECK (
	("broken_at_seq" IS NULL) = ("broken_detected_at" IS NULL)
	AND ("broken_at_seq" IS NULL OR "broken_at_seq" >= 1)
);--> statement-breakpoint
-- ── hand-amended: the WORM copy rows are append-only (the 0006 pattern) ────
-- A copy row records an S3 object version under Object Lock: rewriting it
-- would make the record disagree with the bucket. The same unconditional
-- guard function as the ledger tables, row-level for UPDATE/DELETE and
-- statement-level for TRUNCATE.
CREATE TRIGGER "ledger_anchor_worm_copies_append_only"
	BEFORE UPDATE OR DELETE ON "ledger_anchor_worm_copies"
	FOR EACH ROW EXECUTE FUNCTION "ledger_append_only_guard"();--> statement-breakpoint
CREATE TRIGGER "ledger_anchor_worm_copies_append_only_truncate"
	BEFORE TRUNCATE ON "ledger_anchor_worm_copies"
	FOR EACH STATEMENT EXECUTE FUNCTION "ledger_append_only_guard"();--> statement-breakpoint
-- ── hand-amended: a recorded break is never erased or rewritten ──────────
-- Detection never auto-heals, and the record of a break must not be
-- editable either: DELETE and TRUNCATE are refused, and the ONE legal UPDATE
-- is the acknowledgement — `acknowledged_by`/`acknowledged_at` from both
-- null to both set, every other column unchanged.
CREATE FUNCTION "ledger_chain_breaks_guard"() RETURNS trigger AS $$
BEGIN
	IF TG_OP = 'UPDATE'
		AND OLD."acknowledged_by" IS NULL AND OLD."acknowledged_at" IS NULL
		AND NEW."acknowledged_by" IS NOT NULL AND NEW."acknowledged_at" IS NOT NULL
		AND (NEW."id", NEW."tenant_id", NEW."warehouse_id", NEW."kind", NEW."first_seq", NEW."anchor_id",
		     NEW."reason", NEW."detected_by", NEW."detected_at")
		    IS NOT DISTINCT FROM
		    (OLD."id", OLD."tenant_id", OLD."warehouse_id", OLD."kind", OLD."first_seq", OLD."anchor_id",
		     OLD."reason", OLD."detected_by", OLD."detected_at") THEN
		RETURN NEW;
	END IF;
	RAISE EXCEPTION 'ledger_chain_breaks is append-only except its acknowledgement: % rejected', TG_OP;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER "ledger_chain_breaks_guard"
	BEFORE UPDATE OR DELETE ON "ledger_chain_breaks"
	FOR EACH ROW EXECUTE FUNCTION "ledger_chain_breaks_guard"();--> statement-breakpoint
CREATE TRIGGER "ledger_chain_breaks_guard_truncate"
	BEFORE TRUNCATE ON "ledger_chain_breaks"
	FOR EACH STATEMENT EXECUTE FUNCTION "ledger_chain_breaks_guard"();--> statement-breakpoint
-- ── hand-amended: `broken_at_seq` is never cleared and never raised ───────
-- Once set it may only move DOWN (a lower break found later); an UPDATE that
-- nulls it or raises it is refused.
CREATE FUNCTION "ledger_integrity_state_broken_guard"() RETURNS trigger AS $$
BEGIN
	IF OLD."broken_at_seq" IS NOT NULL
		AND (NEW."broken_at_seq" IS NULL OR NEW."broken_at_seq" > OLD."broken_at_seq") THEN
		RAISE EXCEPTION 'ledger_integrity_state.broken_at_seq is never cleared or raised (% -> %)', OLD."broken_at_seq", NEW."broken_at_seq";
	END IF;
	RETURN NEW;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER "ledger_integrity_state_broken_guard"
	BEFORE UPDATE ON "ledger_integrity_state"
	FOR EACH ROW EXECUTE FUNCTION "ledger_integrity_state_broken_guard"();--> statement-breakpoint
-- ── hand-amended: the notifications source vocabulary, widened ───────────
-- Drop and re-add (the 0023/0024/0070 precedent). Pinned against
-- `NOTIFICATION_SOURCE_TYPES` by test/notifications.spec.ts.
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_source_type_check";--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_source_type_check" CHECK ("source_type" IN (
	'stock-adjustment', 'count-variance', 'over-receipt', 'rejected-op',
	'reorder-breach', 'batch-alert', 'qc-hold', 'channel-sync', 'audit-export',
	'ledger-chain-break'
));--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0056 shape) ─────────
ALTER TABLE "ledger_integrity_state" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "ledger_chain_breaks" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "ledger_anchor_worm_copies" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "ledger_integrity_state_tenant_isolation" ON "ledger_integrity_state"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "ledger_chain_breaks_tenant_isolation" ON "ledger_chain_breaks"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "ledger_anchor_worm_copies_tenant_isolation" ON "ledger_anchor_worm_copies"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0067/0070 model) ────────────────
-- The accepted shapes are inserted first and rolled back by a sentinel, so a
-- CHECK that refuses everything cannot pass. Each refused shape runs in its
-- own subtransaction and must be refused by `check_violation` ON THE NAMED
-- CONSTRAINT — a probe another CHECK happens to refuse proves nothing. The
-- WORM copy table's append-only trigger is probed too (an UPDATE and a
-- DELETE of an accepted row must raise the guard's exception).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	a uuid := gen_random_uuid();
	h text := repeat('ab', 32);
	refused_by text;
	expected text;
	probe text;
	guarded int := 0;
	b uuid := gen_random_uuid();
	sw uuid := gen_random_uuid();
BEGIN
	-- (1) the accepted shapes: both anchor kinds, a copy row, every break kind
	-- and detector (open and acknowledged), a fresh and a broken state row,
	-- and the tenth notification source.
	BEGIN
		INSERT INTO "ledger_anchors" ("id","tenant_id","warehouse_id","from_seq","to_seq","digest","anchored_at","kind")
		VALUES (gen_random_uuid(), t, w, 1, 5, h, now(), 'legacy'),
		       (a, t, w, 6, 9, h, now(), 'verified');
		INSERT INTO "ledger_anchors" ("id","tenant_id","warehouse_id","from_seq","to_seq","digest","anchored_at")
		VALUES (gen_random_uuid(), t, w, 10, 12, h, now());
		IF (SELECT "kind" FROM "ledger_anchors" WHERE "tenant_id" = t AND "to_seq" = 12) <> 'verified' THEN
			RAISE EXCEPTION 'migration 0071: an anchor without a kind did not default to verified.';
		END IF;
		INSERT INTO "ledger_anchor_worm_copies" ("anchor_id","tenant_id","bucket","object_key","version_id","retain_until","copied_at")
		VALUES (a, t, 'b', 'ledger-anchors/k.json', 'v1', now() + interval '7 years', now());
		INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","anchor_id","reason","detected_by","detected_at","acknowledged_by","acknowledged_at")
		VALUES (b, t, w, 'chain', 3, NULL, 'hash mismatch at seq 3', 'anchor', now(), NULL, NULL),
		       (gen_random_uuid(), t, w, 'chain', 4, NULL, 'r', 'reverify', now(), gen_random_uuid(), now()),
		       (gen_random_uuid(), t, w, 'chain', 5, NULL, 'r', 'verify', now(), NULL, NULL),
		       (gen_random_uuid(), t, w, 'worm', 6, a, 'r', 'reverify', now(), NULL, NULL);
		INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at")
		VALUES (t, w, 0, now());
		INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at","verified_through_seq","verified_at","broken_at_seq","broken_detected_at","reverify_after_seq","last_run_at")
		VALUES (t, sw, 5, now(), 9, now(), 3, now(), 9, now());
		INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","warehouse_id","summary","raised_at","surfaced_at")
		VALUES (gen_random_uuid(), t, 'ledger-chain-break', gen_random_uuid(), w, '{}'::jsonb, now(), now());
		-- The copy row is append-only.
		BEGIN
			UPDATE "ledger_anchor_worm_copies" SET "version_id" = 'v2' WHERE "anchor_id" = a;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		BEGIN
			DELETE FROM "ledger_anchor_worm_copies" WHERE "anchor_id" = a;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		BEGIN
			TRUNCATE "ledger_anchor_worm_copies";
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		IF guarded <> 3 THEN
			RAISE EXCEPTION 'migration 0071: the WORM copy append-only triggers did not refuse an UPDATE, a DELETE and a TRUNCATE.';
		END IF;
		-- A break: never deleted, truncated or rewritten; acknowledged once.
		guarded := 0;
		BEGIN
			DELETE FROM "ledger_chain_breaks" WHERE "id" = b;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		BEGIN
			TRUNCATE "ledger_chain_breaks";
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		BEGIN
			UPDATE "ledger_chain_breaks" SET "reason" = 'rewritten' WHERE "id" = b;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		BEGIN
			UPDATE "ledger_chain_breaks" SET "first_seq" = 9, "acknowledged_by" = gen_random_uuid(), "acknowledged_at" = now() WHERE "id" = b;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		IF guarded <> 4 THEN
			RAISE EXCEPTION 'migration 0071: the chain-break guard did not refuse a DELETE, a TRUNCATE and two rewrites.';
		END IF;
		-- The acknowledgement is the one legal UPDATE — and only once.
		UPDATE "ledger_chain_breaks" SET "acknowledged_by" = gen_random_uuid(), "acknowledged_at" = now() WHERE "id" = b;
		BEGIN
			UPDATE "ledger_chain_breaks" SET "acknowledged_by" = gen_random_uuid() WHERE "id" = b;
			RAISE EXCEPTION 'migration 0071: a second acknowledgement was accepted.';
		EXCEPTION WHEN raise_exception THEN
			IF SQLERRM LIKE 'migration 0071:%' THEN RAISE; END IF;
		END;
		-- broken_at_seq: never cleared, never raised; lowering is allowed.
		guarded := 0;
		BEGIN
			UPDATE "ledger_integrity_state" SET "broken_at_seq" = NULL, "broken_detected_at" = NULL WHERE "tenant_id" = t AND "warehouse_id" = sw;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		BEGIN
			UPDATE "ledger_integrity_state" SET "broken_at_seq" = 4 WHERE "tenant_id" = t AND "warehouse_id" = sw;
		EXCEPTION WHEN raise_exception THEN
			guarded := guarded + 1;
		END;
		IF guarded <> 2 THEN
			RAISE EXCEPTION 'migration 0071: the broken_at_seq guard did not refuse a clear and a raise.';
		END IF;
		UPDATE "ledger_integrity_state" SET "broken_at_seq" = 2, "broken_detected_at" = now() WHERE "tenant_id" = t AND "warehouse_id" = sw;
		RAISE EXCEPTION USING ERRCODE = 'P0071', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0071: an accepted shape was refused.';
		WHEN SQLSTATE 'P0071' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) the refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown anchor kind',
		'unknown break kind',
		'unknown detector',
		'acknowledged_by without acknowledged_at',
		'acknowledged_at without acknowledged_by',
		'worm without an anchor',
		'chain with an anchor',
		'break at seq 0',
		'negative legacy_through_seq',
		'negative reverify_after_seq',
		'negative verified_through_seq',
		'broken_at_seq without broken_detected_at',
		'broken_detected_at without broken_at_seq',
		'broken at seq 0',
		'unknown source type'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown anchor kind' THEN 'ledger_anchors_kind_check'
			WHEN 'unknown break kind' THEN 'ledger_chain_breaks_kind_check'
			WHEN 'unknown detector' THEN 'ledger_chain_breaks_detected_by_check'
			WHEN 'acknowledged_by without acknowledged_at' THEN 'ledger_chain_breaks_ack_check'
			WHEN 'acknowledged_at without acknowledged_by' THEN 'ledger_chain_breaks_ack_check'
			WHEN 'worm without an anchor' THEN 'ledger_chain_breaks_anchor_check'
			WHEN 'chain with an anchor' THEN 'ledger_chain_breaks_anchor_check'
			WHEN 'break at seq 0' THEN 'ledger_chain_breaks_first_seq_check'
			WHEN 'negative legacy_through_seq' THEN 'ledger_integrity_state_seq_check'
			WHEN 'negative reverify_after_seq' THEN 'ledger_integrity_state_seq_check'
			WHEN 'negative verified_through_seq' THEN 'ledger_integrity_state_seq_check'
			WHEN 'unknown source type' THEN 'notifications_source_type_check'
			ELSE 'ledger_integrity_state_broken_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown anchor kind' THEN
					INSERT INTO "ledger_anchors" ("id","tenant_id","warehouse_id","from_seq","to_seq","digest","anchored_at","kind")
					VALUES (gen_random_uuid(), t, w, 1, 1, h, now(), 'baseline');
				WHEN 'unknown break kind' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","reason","detected_by","detected_at")
					VALUES (gen_random_uuid(), t, w, 'gap', 1, 'r', 'anchor', now());
				WHEN 'unknown detector' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","reason","detected_by","detected_at")
					VALUES (gen_random_uuid(), t, w, 'chain', 1, 'r', 'worker', now());
				WHEN 'acknowledged_by without acknowledged_at' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","reason","detected_by","detected_at","acknowledged_by")
					VALUES (gen_random_uuid(), t, w, 'chain', 1, 'r', 'anchor', now(), gen_random_uuid());
				WHEN 'acknowledged_at without acknowledged_by' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","reason","detected_by","detected_at","acknowledged_at")
					VALUES (gen_random_uuid(), t, w, 'chain', 1, 'r', 'anchor', now(), now());
				WHEN 'worm without an anchor' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","reason","detected_by","detected_at")
					VALUES (gen_random_uuid(), t, w, 'worm', 1, 'r', 'reverify', now());
				WHEN 'chain with an anchor' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","anchor_id","reason","detected_by","detected_at")
					VALUES (gen_random_uuid(), t, w, 'chain', 1, a, 'r', 'reverify', now());
				WHEN 'break at seq 0' THEN
					INSERT INTO "ledger_chain_breaks" ("id","tenant_id","warehouse_id","kind","first_seq","reason","detected_by","detected_at")
					VALUES (gen_random_uuid(), t, w, 'chain', 0, 'r', 'anchor', now());
				WHEN 'negative legacy_through_seq' THEN
					INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at")
					VALUES (t, gen_random_uuid(), -1, now());
				WHEN 'negative reverify_after_seq' THEN
					INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at","reverify_after_seq")
					VALUES (t, gen_random_uuid(), 0, now(), -1);
				WHEN 'negative verified_through_seq' THEN
					INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at","verified_through_seq","verified_at")
					VALUES (t, gen_random_uuid(), 0, now(), -1, now());
				WHEN 'broken_at_seq without broken_detected_at' THEN
					INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at","broken_at_seq")
					VALUES (t, gen_random_uuid(), 0, now(), 3);
				WHEN 'broken_detected_at without broken_at_seq' THEN
					INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at","broken_detected_at")
					VALUES (t, gen_random_uuid(), 0, now(), now());
				WHEN 'broken at seq 0' THEN
					INSERT INTO "ledger_integrity_state" ("tenant_id","warehouse_id","legacy_through_seq","baselined_at","broken_at_seq","broken_detected_at")
					VALUES (t, gen_random_uuid(), 0, now(), 0, now());
				WHEN 'unknown source type' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'ledger-break', gen_random_uuid(), '{}'::jsonb, now(), now());
			END CASE;
		EXCEPTION WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS NULL THEN
			RAISE EXCEPTION 'migration 0071: the CHECK probe "%" was not refused.', probe;
		END IF;
		IF refused_by <> expected THEN
			RAISE EXCEPTION 'migration 0071: the CHECK probe "%" was refused by % — expected %.', probe, refused_by, expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "ledger_anchors" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "ledger_anchor_worm_copies" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "ledger_chain_breaks" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "ledger_integrity_state" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "notifications" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0071: a CHECK probe row survived.';
	END IF;
END $$;
